package com.soumyajit.gradlemc.investigation;
import java.time.*;import java.util.*;
public final class InvestigationSelfTest {private InvestigationSelfTest(){}public static void run(){ids();transitions();manifest();}private static void ids(){ok(new InvestigationId("inv-1"));for(String x:List.of("","INV","con","a/../b","a..b","a b","a\\b","a:","a."))bad(()->new InvestigationId(x));check(InvestigationId.generate(Clock.fixed(Instant.EPOCH,ZoneOffset.UTC),UUID.fromString("00000000-0000-0000-0000-000000000001")).value().startsWith("inv-0-"));}private static void transitions(){InvestigationStateMachine.requireTransition(InvestigationState.CREATED,InvestigationState.RUNNING);InvestigationStateMachine.requireTransition(InvestigationState.RUNNING,InvestigationState.COMPLETED);for(InvestigationState a:InvestigationState.values())for(InvestigationState b:InvestigationState.values())if(!(a==InvestigationState.CREATED&&(b==InvestigationState.RUNNING||b==InvestigationState.CANCELLED||b==InvestigationState.FAILED)||a==InvestigationState.RUNNING&&(b==InvestigationState.COMPLETED||b==InvestigationState.COMPLETED_WITH_LIMITATIONS||b==InvestigationState.CANCELLED||b==InvestigationState.FAILED)))bad(()->InvestigationStateMachine.requireTransition(a,b));}private static void manifest(){Instant t=Instant.EPOCH;InvestigationManifest m=new InvestigationManifest(1,0,new InvestigationId("inv-1"),new InvestigationProfileId("placeholder"),"1",InvestigationState.CREATED,t,null,null,new InvestigationRuntimeIdentity("1.0.3","1.20.1","47.4.20","COMMON"),"fingerprint",List.of(),List.of(),List.of(),Optional.empty(),false,List.of(),1,false);check(m.steps().isEmpty());bad(()->new InvestigationManifest(1,0,m.id(),m.profileId(),"1",InvestigationState.FAILED,t,t,t,m.runtimeIdentity(),"f",List.of(),List.of(),List.of(),Optional.empty(),false,List.of(),1,false));bad(()->new InvestigationManifest(1,0,m.id(),m.profileId(),"1",InvestigationState.COMPLETED_WITH_LIMITATIONS,t,t,t,m.runtimeIdentity(),"f",List.of(),List.of(),List.of(),Optional.empty(),false,List.of(),1,false));}private static void ok(Object x){}private static void bad(Runnable r){try{r.run();throw new AssertionError("expected rejection");}catch(IllegalArgumentException|IllegalStateException expected){}}private static void check(boolean b){if(!b)throw new AssertionError("Investigation domain self-test failed");}}
